    pub async fn get_stats(&self) -> Result<serde_json::Value, QNetError> {
        let height = self.get_height().await;
        let peer_count = self.get_peer_count().await?;
        let mempool_size = self.get_mempool_size().await?;
        let regional_health = self.get_regional_health();
        
        Ok(serde_json::json!({
            "height": height,
            "peers": peer_count,
            "mempool_size": mempool_size,
            "regional_health": regional_health,
            "node_type": format!("{:?}", self.node_type),
            "region": format!("{:?}", self.region),
            "node_id": self.node_id,
            "sharding_enabled": self.perf_config.enable_sharding,
            "parallel_validation": self.perf_config.parallel_validation,
        }))
    }
    
    /// Start sync process after node restart or new node join
    pub async fn start_sync_if_needed(&self) -> Result<(), QNetError> {
        // CRITICAL: Mark node as syncing to prevent consensus participation
        if is_info() { println!("[INFO][SYNC] sync_check_start"); }
        
        // Set a flag that we're syncing (prevents producing blocks)
        let _is_syncing = Arc::new(std::sync::atomic::AtomicBool::new(true));
        
        // PRODUCTION: Try to load from snapshot first for fast sync
        if let Ok(latest_snapshot) = self.storage.get_latest_snapshot_height() {
            if let Some(snapshot_height) = latest_snapshot {
                let current_height = self.get_height().await;
                
                // If we're far behind and have a snapshot, use it
                if current_height < snapshot_height.saturating_sub(1000) {
                    println!("[INFO][SYNC] snapshot_found h={} loading=true", snapshot_height);
                    
                    // Local own snapshot (trusted, self-created) → load directly into live state.
                    if let Err(e) = self.storage.load_state_snapshot(snapshot_height, false).await {
                        println!("[WARN][SYNC] Failed to load snapshot: {}, falling back to normal sync", e);
                    } else {
                        // Update our height to snapshot height
                        *self.height.write().await = snapshot_height;
                        if is_info() { println!("[INFO][SYNC] snapshot_loaded h={}", snapshot_height); }
                        // Heal reward shards the snapshot carried a root but not a leaf-set for (certified-verified).
                        let _ = Self::backfill_reward_shards(&self.storage);
                        
                        // Continue syncing from snapshot height
                        if let Some(ref p2p) = self.unified_p2p {
                            if let Some(network_height) = p2p.get_cached_network_height() {
                                if network_height > snapshot_height {
                                    println!("[INFO][SYNC] post_snapshot_sync blocks={}-{}", snapshot_height + 1, network_height);
                                    return self.sync_blocks(snapshot_height + 1, network_height).await;
                                }
                            }
                        }
                        return Ok(());
                    }
                }
            }
        }
        
        // Check if we have pending sync from previous run
        if let Ok(Some((_from, to, current))) = self.storage.load_sync_progress() {
            if is_info() { println!("[INFO][SYNC] resume from={} to={}", current, to); }
            
            if let Some(ref p2p) = self.unified_p2p {
                // Continue sync from where we left off
                if let Err(e) = p2p.batch_sync(current, to, 100).await {
                    return Err(QNetError::SyncError(format!("Sync failed: {}", e)));
                }
                
                // Clear sync progress after successful completion
                self.storage.clear_sync_progress()?;
                if is_info() { println!("[INFO][SYNC] sync_ok"); }
            }
        } else {
            // Check if we're behind the network
            if let Some(ref p2p) = self.unified_p2p {
                let peers = p2p.get_validated_active_peers();
                if !peers.is_empty() {
                    let current_height = self.get_height().await;
                    
                    // CRITICAL FIX: Query network height from peers
                    let network_height = self.query_network_height().await?;
                    
                    if is_debug() { println!("[DBG][SYNC] local={} net={}", current_height, network_height); }
                    
                    // If we're behind, start sync
                    if network_height > current_height + 10 { // Allow 10 block tolerance
                        println!("[WARN][SYNC] Node is {} blocks behind, starting sync...", 
                                 network_height - current_height);
                        
                        // Light nodes are thin clients - they don't sync blocks
                        // They get all data (balance, TX history) via RPC from Super nodes
                        if self.node_type == NodeType::Light {
                            if is_info() { println!("[INFO][SYNC] light_node_skip reason=thin_client"); }
                        } else {
                            // Super nodes sync complete history
                            // For new nodes (height 0 or 1), start from block 1 (first microblock)
                            let sync_from = if current_height <= 1 { 1 } else { current_height + 1 };
                            
                            // Sync to network height
                            self.sync_blocks(sync_from, network_height).await?;
                            
                            // PRODUCTION v2.19.12: Sync macroblocks for Super nodes
                            // Macroblocks contain consensus data and state roots
                            let local_macro_index = current_height / 90;
                            let network_macro_index = network_height / 90;
                            if network_macro_index > local_macro_index {
                                if is_info() {
                                    println!("[INFO][MACROBLOCK-SYNC] syncing_macroblocks from={} to={}", 
                                             local_macro_index + 1, network_macro_index);
                                }
                                self.sync_macroblocks(local_macro_index + 1, network_macro_index).await?;
                            }
                        }
                    } else {
                        if is_info() { println!("[INFO][SYNC] up_to_date"); }
                    }
                } else {
                    println!("[WARN][SYNC] No peers available for sync check");
                }
            }
        }
        
        Ok(())
    }
    
    /// Sync blocks from network
    pub async fn sync_blocks(&self, from_height: u64, to_height: u64) -> Result<(), QNetError> {
        // v13.0: Guard against inverted ranges (from > to)
        // This can happen when height calculations underflow or peers report stale data.
        // Without this guard, `from..=to` with from > to creates an empty range but
        // save_sync_progress records a broken state → infinite empty sync loop on restart.
        if from_height > to_height {
            if is_warn() {
                println!("[WARN][SYNC] inverted_range from={} to={} skipped", from_height, to_height);
            }
            return Ok(());
        }

        if let Some(ref p2p) = self.unified_p2p {
            // Start sync process
            if is_info() { println!("[INFO][SYNC] block_sync {}-{}", from_height, to_height); }
            
            // Save sync progress for recovery
            self.storage.save_sync_progress(from_height, to_height, from_height)?;
            
            // Use batch sync for efficiency
            if let Err(e) = p2p.batch_sync(from_height, to_height, 100).await {
                return Err(QNetError::SyncError(format!("Batch sync failed: {}", e)));
            }
            
            // Clear sync progress after success
            self.storage.clear_sync_progress()?;
            if is_info() { println!("[INFO][SYNC] sync_complete"); }
            
            Ok(())
        } else {
            Err(QNetError::NetworkError("P2P network not initialized".to_string()))
        }
    }
    
    /// Handle incoming sync request from peer
    /// CRITICAL FIX v2.61: Size-based batched sync to prevent QUIC message loss
    /// v5.6: Added from_peer_addr for routing responses to unregistered new nodes
    pub async fn handle_sync_request(&self, from_height: u64, to_height: u64, requester_id: String, from_peer_addr: String) -> Result<(), QNetError> {
        // v13.0: Guard against inverted sync requests from peers
        if from_height > to_height {
            if is_warn() {
                println!("[WARN][SYNC] inverted_request from={} addr={} heights={}-{} rejected",
                         requester_id, from_peer_addr, from_height, to_height);
            }
            return Ok(());
        }

        if is_debug() {
            println!("[DBG][SYNC] serve_request from={} addr={} heights={}-{}", requester_id, from_peer_addr, from_height, to_height);
        }

        // Get microblocks from storage (already in network format)
        let blocks_data = self.storage.get_microblocks_range(from_height, to_height).await?;
        
        if is_trace() { 
            println!("[TRC][SYNC] get_range({}, {}) blocks={}", from_height, to_height, blocks_data.len()); 
        }
        
        if blocks_data.is_empty() {
            if is_debug() { println!("[DBG][SYNC] empty_range heights={}-{} sending_empty_batch", from_height, to_height); }
            // v6.5 FIX: ALWAYS send a response, even for empty ranges
            // PROBLEM: Silent return Ok(()) caused requesting node to timeout after 2s
            //   with "3 peers did not respond for h=0-0" — infinite retry loop
            // SOLUTION: Send empty BlocksBatch so requester knows range is empty
            //   This is standard P2P protocol: every request gets a response.
            //   (Ethereum devp2p, libp2p — always respond with data or empty)
            if let Some(ref p2p) = self.unified_p2p {
                let peer_addr = p2p.get_peer_address_by_id(&requester_id)
                    .or_else(|| {
                        let peers = p2p.get_validated_active_peers();
                        peers.iter().find(|p| p.id == requester_id).map(|p| p.addr.clone())
                    })
                    .or_else(|| {
                        if !from_peer_addr.is_empty() { Some(from_peer_addr.clone()) } else { None }
                    });

                if let Some(addr) = peer_addr {
                    let empty_response = crate::unified_p2p::NetworkMessage::BlocksBatch {
                        blocks: Vec::new(),
                        from_height,
                        to_height,
                        sender_id: self.node_id.clone(),
                    };
                    p2p.send_network_message(&addr, empty_response);
                    // Co-send signed head even on an empty serve so a behind follower's SIGNED_HEAD_MAX
                    // still refreshes — breaks the request-vs-behind loop.
                    p2p.cosend_signed_head(&addr);
                    if is_info() { println!("[INFO][SYNC] empty_batch_sent to={} addr={}", requester_id, addr); }
                } else {
                    if is_warn() { println!("[WARN][SYNC] empty_batch_no_addr id={} from={}", requester_id, from_peer_addr); }
                }
            }
            return Ok(());
        }
        
        if let Some(ref p2p) = self.unified_p2p {
            // ═══════════════════════════════════════════════════════════════════════════
            // CRITICAL FIX v2.61: SIZE-BASED BATCHING for intercontinental reliability
            // ═══════════════════════════════════════════════════════════════════════════
            // Problem: Sending large messages via QUIC = fragmentation = packet loss = failure
            // Root cause: 101 blocks with 50K TX each = ~10MB, any UDP packet loss = "Message too short"
            // Solution: Batch by SIZE (not count) - max 1MB per message (safe for QUIC/UDP)
            // 
            // Why SIZE matters more than COUNT:
            // - Empty block: ~20KB
            // - Block with 50K TX: ~12MB!
            // - 10 empty blocks: 200KB (OK)
            // - 1 block with 50K TX: 12MB (FAIL)
            // ═══════════════════════════════════════════════════════════════════════════
            const MAX_BATCH_SIZE_BYTES: usize = 1_000_000;  // 1MB max per QUIC message
            const SYNC_BATCH_DELAY_MS: u64 = 5;  // 5ms pacing between batches
            
            // Find peer address
            // v5.6: Use from_peer_addr as fallback for new nodes not yet in peer registry
            let peer_addr = p2p.get_peer_address_by_id(&requester_id)
                .or_else(|| {
                    let peers = p2p.get_validated_active_peers();
                    peers.iter().find(|p| p.id == requester_id).map(|p| p.addr.clone())
                })
                .or_else(|| {
                    if !from_peer_addr.is_empty() {
                        if is_info() { println!("[INFO][SYNC] using_from_peer_addr id={} addr={}", requester_id, from_peer_addr); }
                        Some(from_peer_addr.clone())
                    } else {
                        None
                    }
                });

            let Some(addr) = peer_addr else {
                if is_info() { println!("[WARN][SYNC] peer_not_found id={} from_addr={}", requester_id, from_peer_addr); }
                return Ok(());
            };
            
            // ═══════════════════════════════════════════════════════════════════════════
            // CRITICAL FIX v2.61: Large blocks (>1MB) use ShredProtocol for reliability
            // Small blocks use batched BlocksBatch messages
            // blocks_data is Vec<(u64, Vec<u8>)> - already (height, data) pairs
            // ═══════════════════════════════════════════════════════════════════════════
            const SHRED_THRESHOLD_BYTES: usize = 1_000_000;  // Blocks >1MB use ShredProtocol
            
            // Separate large blocks (ShredProtocol) from small blocks (BatchSync)
            let mut large_blocks: Vec<(u64, Vec<u8>)> = Vec::new();
            let mut small_blocks: Vec<(u64, Vec<u8>)> = Vec::new();
            let mut total_size: usize = 0;
            
            for (height, block_data) in &blocks_data {
                let block_size = block_data.len();
                total_size += block_size;
                
                if block_size > SHRED_THRESHOLD_BYTES {
                    large_blocks.push((*height, block_data.clone()));
                } else {
                    small_blocks.push((*height, block_data.clone()));
                }
            }
            
            // Send large blocks via ShredProtocol (reliable for 20MB+)
            if !large_blocks.is_empty() {
                if is_info() {
                    println!("[INFO][SYNC] sending {} large blocks via ShredProtocol to={}", 
                             large_blocks.len(), requester_id);
                }
                for (height, block_data) in large_blocks {
                    p2p.send_block_via_shred_to_peer(&addr, height, block_data, false).await;
                }
            }
            
            // Build size-based batches for small blocks
            // BlocksBatch.blocks is Vec<(u64, Vec<u8>)> - (height, data) pairs
            let mut batches: Vec<Vec<(u64, Vec<u8>)>> = Vec::new();
            let mut batch_heights: Vec<(u64, u64)> = Vec::new();  // (from, to) for each batch
            let mut current_batch: Vec<(u64, Vec<u8>)> = Vec::new();
            let mut current_batch_size: usize = 0;
            let mut batch_start_height: Option<u64> = None;
            let mut last_height: u64 = 0;
            
            for (height, block) in &small_blocks {
                let block_size = block.len();
                
                // If adding this block exceeds limit, start new batch
                if current_batch_size + block_size > MAX_BATCH_SIZE_BYTES && !current_batch.is_empty() {
                    batches.push(current_batch);
                    batch_heights.push((batch_start_height.unwrap_or(*height), last_height));
                    current_batch = Vec::new();
                    current_batch_size = 0;
                    batch_start_height = None;
                }
                
                if batch_start_height.is_none() {
                    batch_start_height = Some(*height);
                }
                last_height = *height;
                
                current_batch.push((*height, block.clone()));
                current_batch_size += block_size;
            }
            
            // Don't forget last batch
            if !current_batch.is_empty() {
                batches.push(current_batch);
                batch_heights.push((batch_start_height.unwrap_or(from_height), last_height));
            }
            
            let num_batches = batches.len();
            let total_blocks = blocks_data.len();
            let small_blocks_count = small_blocks.len();
            let large_blocks_count = total_blocks - small_blocks_count;
            
            if is_debug() {
                println!("[DBG][SYNC] sending blocks={} (small={} large={}) size={}KB batches={} to={}",
                         total_blocks, small_blocks_count, large_blocks_count,
                         total_size / 1024, num_batches, requester_id); 
            }
            
            // Send small blocks batches with pacing
            for (batch_idx, batch) in batches.iter().enumerate() {
                let (batch_from, batch_to) = batch_heights.get(batch_idx)
                    .copied()
                    .unwrap_or((from_height, from_height));
                
                let response = NetworkMessage::BlocksBatch {
                    blocks: batch.clone(),
                    from_height: batch_from,
                    to_height: batch_to,
                    sender_id: self.node_id.clone(),
                };
                
                p2p.send_network_message(&addr, response);
                
                if is_debug() { 
                    let batch_size: usize = batch.iter().map(|(_, b)| b.len()).sum();
                    println!("[DBG][SYNC] batch={}/{} heights={}-{} size={}KB", 
                             batch_idx + 1, num_batches, batch_from, batch_to, batch_size / 1024); 
                }
                
                // Pacing delay between batches (except last)
                if batch_idx < num_batches - 1 {
                    tokio::time::sleep(std::time::Duration::from_millis(SYNC_BATCH_DELAY_MS)).await;
                }
            }

            // Co-send our signed head over the serve channel so the requester (incl. a freshly-joined
            // cold node the HealthPing emit fan-out misses) learns the real network tip and advances
            // its SIGNED_HEAD_MAX, instead of stalling at its own frontier.
            p2p.cosend_signed_head(&addr);

            if is_info() {
                println!("[INFO][SYNC] sent blocks={} (shred={} batch={}) to={}",
                         total_blocks, large_blocks_count, small_blocks_count, requester_id);
            }
        }
        
        Ok(())
    }
    
    // =========================================================================
    // MACROBLOCK SYNC METHODS (PRODUCTION v2.19.12)
    // =========================================================================
    
    /// Handle incoming macroblock sync request from peer
    /// PRODUCTION: Full macroblock sync support for new nodes joining network
    /// CRITICAL FIX v2.61: Size-based batched sync to prevent QUIC message loss
    pub async fn handle_macroblock_sync_request(&self, from_index: u64, to_index: u64, requester_id: String) -> Result<(), QNetError> {
        if is_info() { 
            println!("[INFO][MB-SYNC] request from={} indices={}-{}", requester_id, from_index, to_index); 
        }
        
        // Get macroblocks from storage
        let macroblocks_data = self.storage.get_macroblocks_range(from_index, to_index).await?;
        
        if is_trace() { 
            println!("[TRC][MB-SYNC] get_range({}, {}) macroblocks={}", from_index, to_index, macroblocks_data.len()); 
        }
        
        if macroblocks_data.is_empty() {
            if is_debug() { println!("[DBG][MB-SYNC] empty_response indices={}-{}", from_index, to_index); }
            return Ok(());
        }
        
        if let Some(ref p2p) = self.unified_p2p {
            // Size-based batching for macroblocks. The old 500 KB cap forced
            // ~1 macroblock/response → catch-up throttled to the per-batch
            // RTT. 5 MB packs ~10 macroblocks/response while staying under
            // the 87 MB SHRED ceiling and 16 MB QUIC stream window; the
            // 80 MB MAX_BLOCK_SIZE_BYTES cap + QUIC memory ceilings still hold.
            const MAX_BATCH_SIZE_BYTES: usize = 5_000_000;  // 5 MB max per message (≤10 macroblocks per response)
            const MB_SYNC_BATCH_DELAY_MS: u64 = 10;  // 10ms pacing between batches
            
            // Find peer address
            let peer_addr = p2p.get_peer_address_by_id(&requester_id)
                .or_else(|| {
                    let peers = p2p.get_validated_active_peers();
                    peers.iter().find(|p| p.id == requester_id).map(|p| p.addr.clone())
                });
            
            let Some(addr) = peer_addr else {
                if is_info() { println!("[WARN][MB-SYNC] peer_not_found id={}", requester_id); }
                return Ok(());
            };
            
            // Build size-based batches
            // macroblocks_data is already Vec<(u64, Vec<u8>)> - (index, data) pairs
            let mut batches: Vec<Vec<(u64, Vec<u8>)>> = Vec::new();
            let mut current_batch: Vec<(u64, Vec<u8>)> = Vec::new();
            let mut current_batch_size: usize = 0;
            let mut total_size: usize = 0;
            
            for (mb_index, mb_data) in &macroblocks_data {
                let mb_size = mb_data.len();
                total_size += mb_size;
                
                // If single macroblock exceeds limit, send it alone
                if mb_size > MAX_BATCH_SIZE_BYTES {
                    if !current_batch.is_empty() {
                        batches.push(current_batch);
                        current_batch = Vec::new();
                        current_batch_size = 0;
                    }
                    batches.push(vec![(*mb_index, mb_data.clone())]);
                    continue;
                }
                
                // If adding this macroblock exceeds limit, start new batch
                if current_batch_size + mb_size > MAX_BATCH_SIZE_BYTES && !current_batch.is_empty() {
                    batches.push(current_batch);
                    current_batch = Vec::new();
                    current_batch_size = 0;
                }
                
                current_batch.push((*mb_index, mb_data.clone()));
                current_batch_size += mb_size;
            }
            
            if !current_batch.is_empty() {
                batches.push(current_batch);
            }
            
            let num_batches = batches.len();
            let total_macroblocks = macroblocks_data.len();
            
            if is_info() { 
                println!("[INFO][MB-SYNC] sending macroblocks={} size={}KB batches={} to={}", 
                         total_macroblocks, total_size / 1024, num_batches, requester_id); 
            }
            
            // Send batches with pacing
            for (batch_idx, batch) in batches.iter().enumerate() {
                // Get from/to from actual batch content
                let batch_from = batch.first().map(|(idx, _)| *idx).unwrap_or(from_index);
                let batch_to = batch.last().map(|(idx, _)| *idx).unwrap_or(batch_from);
                
                let response = NetworkMessage::MacroblocksBatch {
                    macroblocks: batch.clone(),
                    from_index: batch_from,
                    to_index: batch_to,
                    sender_id: self.node_id.clone(),
                };
                
                p2p.send_network_message(&addr, response);
                
                if is_debug() { 
                    let batch_size: usize = batch.iter().map(|(_, b)| b.len()).sum();
                    println!("[DBG][MB-SYNC] batch={}/{} indices={}-{} size={}KB", 
                             batch_idx + 1, num_batches, batch_from, batch_to, batch_size / 1024); 
                }
                
                if batch_idx < num_batches - 1 {
                    tokio::time::sleep(std::time::Duration::from_millis(MB_SYNC_BATCH_DELAY_MS)).await;
                }
            }
            
            if is_info() { 
                println!("[INFO][MB-SYNC] sent macroblocks={} batches={} to={}", total_macroblocks, num_batches, requester_id); 
            }
        }
        
        Ok(())
    }
    
    /// Process received macroblock from network sync
    /// PRODUCTION: Validates and saves macroblock to storage
    /// Consensus committee for a v2 checkpoint index, derived EXACTLY as the proposer
    /// did: candidates from the N-2 snapshot (genesis list for epochs ≤2) →
    /// select_consensus_committee VRF-sample ≤CONSENSUS_COMMITTEE_SIZE. Used to verify a
    /// received QC against the real committee, not the self-declared one.
    /// P1-D: the macroblock index (N-2) whose STORED macroblock anchors window `index`'s committee
    /// derivation (calculate_qualified_candidates' eligible set + the VRF subsample seed). Returns
    /// None for the bootstrap windows (index<3) that use the deterministic genesis anchor and need no
    /// on-chain N-2. A node lacking this macroblock must DEFER QC verification rather than let
    /// derive_v2_committee WALK BACK to a different anchor — a walked-back committee differs from the
    /// sealer's → a spurious `v2_qc_invalid` that SPLITS honest nodes (a node with a storage gap
    /// rejects a validly-finalized macroblock). Pure ⇒ unit-tested for the off-by-one genesis boundary.
    fn v2_committee_anchor_index(index: u64) -> Option<u64> {
        if index >= 3 { Some(index - 2) } else { None }
    }

    /// Canonical FULL verification of a v2 macroblock's checkpoint QC — the SINGLE authority used
    /// by EVERY macroblock-accept path so none can be bypassed (H1). It:
    ///  (1) binds the block to the QC: window == index AND cp.hash() == qc.checkpoint_hash;
    ///  (2) binds EVERY consensus-critical BODY field to the QC-certified checkpoint — state_root,
    ///      micro_blocks, randomness_beacon, timestamp — all of which live inside cp.hash() that the
    ///      QC signs (H2: an un-bound `randomness_beacon` let a relayed body carry a different beacon
    ///      than the QC-agreed one → poisoned the next epoch's committee/leader seed → split);
    ///  (3) DEFERS (Err) if the canonical N-2 committee anchor is not local (P1-D anti-walk-back);
    ///  (4) derives the committee DETERMINISTICALLY (N-2 / genesis) — NOT the self-declared
    ///      `consensus_committee` an attacker could set to their own keys;
    ///  (5) checks epoch_commitment (published validator set matches the QC commitment);
    ///  (6) Dilithium-verifies EVERY committee signature. A forged committee or any invalid/zero
    ///      signature cannot pass. Returns Ok(()) for a non-v2 (legacy) macroblock — the caller
    ///      handles that path.
    pub(crate) async fn verify_v2_macroblock(
        macroblock: &qnet_state::MacroBlock,
        index: u64,
        p2p: &Arc<SimplifiedP2P>,
        node_id: &str,
        node_type: NodeType,
        storage: &Storage,
    ) -> Result<(), String> {
        // v2 finality IS the 2f+1 checkpoint QC — a None-QC macroblock has no finality to verify and
        // must never be trusted. Erroring here (rather than Ok) keeps the invariant LOCAL to the verifier:
        // "verify_v2_macroblock Ok ⇒ a checkpoint QC was present and Dilithium-verified", so no current or
        // future caller can accept a None-QC macroblock by trusting the verifier alone.
        let cp_qc = match macroblock.consensus_data.checkpoint_qc.as_ref() {
            Some(b) => b,
            None => return Err(format!("v2_qc_absent mb={}", index)),
        };
        let (cp, qc): (qnet_consensus::checkpoint_bft::Checkpoint, qnet_consensus::checkpoint_bft::QuorumCertificate) =
            bincode::deserialize(cp_qc).map_err(|e| format!("v2_qc_decode mb={} err={}", index, e))?;
        if cp.window_head_height / 90 != index || cp.hash() != qc.checkpoint_hash {
            return Err(format!("v2_qc_unbound mb={}", index));
        }
        // Weak-subjectivity trust root — INERT at the fresh-genesis pin (0,zeros). The cold-join lineage
        // walk re-verifies macroblock QCs UP from an EXOGENOUS root so a byzantine snapshot server cannot
        // root the committee in its own peer-served data (the circular-anchor forge). Two roots:
        //   • genesis (pin=0): the first two macroblocks (head ≤180) use the embedded genesis committee;
        //   • mature (pin>0): the binary-pinned macroblock is trusted by HASH, and its immediate
        //     predecessor by the macroblock previous_hash chain — together the two N-2 committee sources
        //     that bootstrap forward QC verification of both parities. Below the pinned pair is trusted
        //     history we neither hold nor re-verify (Err ⇒ resync above the floor).
        // `pin` = the inductive hash-trust ROOT = max-by-index of the binary WS pin and the adopted GALC
        // capsule (both genesis-key-rooted; never the snapshot's own self-reported hash). It carries the
        // committee_digest (pin.2). `ws` = runtime FLOOR (max of binary pin and the locally-adopted
        // snapshot anchor) — the below-which-we-don't-re-verify gate, kept SEPARATE so a capsule never
        // advances finality (that stays gated on the full snapshot binding).
        let pin = crate::galc::effective_pin_checkpoint();
        let ws = effective_ws_checkpoint();
        if pin.0 > 0 && index == pin.0 {
            // Hash-trust the pinned macroblock K AND bind its committee-derivation inputs (eligible_
            // producers + beacon) to the pinned ANCHOR digest. MacroBlock::hash() omits consensus_data,
            // so without this digest a hash-equal K with forged producers would be stored and poison the
            // forward committee. Checking K's OWN fields here (not K-1's) needs only K ⇒ no K↔K-1
            // deadlock, and it rejects a forged K at STORE time via ANY ingress (walk, standalone
            // MacroblockAnchor, snapshot-anchor==pin.0), not only the contiguous walk.
            if macroblock.hash()[..] != pin.1[..] {
                return Err(format!("v2_ws_pin_mismatch mb={}", index));
            }
            if crate::galc::committee_fields_digest(macroblock) != pin.2 {
                return Err(format!("v2_ws_pin_committee_mismatch mb={}", index));
            }
            return Ok(());
        }
        if pin.0 > 1 && index == pin.0 - 1 {
            // Predecessor K-1: trusted by K's previous_hash chain (K is stored first, by hash above) AND
            // bound to the pinned PRED digest over ITS OWN committee fields. Each branch checks only its
            // own macroblock's digest, so neither needs the other's consensus_data ⇒ no deadlock.
            return match storage.get_macroblock_by_height(pin.0).ok().flatten()
                .and_then(|b| bincode::deserialize::<qnet_state::MacroBlock>(&b).ok())
            {
                Some(anchor) if anchor.previous_hash[..] == macroblock.hash()[..] => {
                    if crate::galc::committee_fields_digest(macroblock) != pin.3 {
                        Err(format!("v2_ws_pin_committee_mismatch mb={}", index))
                    } else { Ok(()) }
                }
                Some(_) => Err(format!("v2_ws_pin_pred_mismatch mb={}", index)),
                None => Err(format!("v2_qc_defer_anchor mb={} need_pin={}", index, pin.0)),
            };
        }
        if index < ws.0 {
            return Err(format!("v2_below_ws mb={} ws={}", index, ws.0));
        }
        if cp.window_mb_hashes != macroblock.micro_blocks
            || cp.state_root != macroblock.state_root
            || macroblock.consensus_data.randomness_beacon != Some(cp.beacon)
            || macroblock.timestamp != cp.timestamp
        {
            return Err(format!("v2_body_mismatch mb={}", index));
        }
        // Decouple (P4): a standalone macroblock whose OWN 2f+1 QC verifies (below) needs its N-2
        // committee anchor only when that anchor is ABOVE the WS checkpoint; at/below WS the committee
        // is binary-trusted, so the lineage walk stops at WS, not genesis. INERT at ws=0 (n2=index-2>=1
        // > 0 for every index with an anchor), i.e. identical to the prior unconditional defer. In the
        // cold-join ASCENDING walk the N-2 anchor is not merely PRESENT but already VERIFIED (it was
        // verify-then-saved earlier in the same walk), so presence here implies a genesis/pin-rooted
        // committee source — never a peer-chosen one.
        if let Some(n2) = Self::v2_committee_anchor_index(index) {
            if n2 > ws.0 && storage.get_macroblock_by_height(n2).ok().flatten().is_none() {
                return Err(format!("v2_qc_defer_anchor mb={} need_mb_n2={}", index, n2));
            }
        }
        let qualified = Self::calculate_qualified_candidates(p2p, node_id, node_type, cp.window_head_height).await;
        let mut ids: Vec<String> = qualified.iter().map(|(id, _)| id.clone()).collect();
        ids.sort();
        let committee = Self::select_consensus_committee(&ids, index, storage);
        if qnet_consensus::checkpoint_bft::quorum_size(committee.len()) == 0 {
            return Err(format!("v2_qc_no_committee mb={}", index));
        }
        let elig = macroblock.consensus_data.eligible_producers.as_deref().unwrap_or(&[]);
        let cmt = macroblock.consensus_data.consensus_committee.clone().unwrap_or_default();
        // The stored ban set is QC-bound via epoch_commitment: deserialize the body's bytes and
        // reject if the recomputed commitment doesn't match the checkpoint's ⇒ a relayer-corrupted
        // banned_validators can never pass, so load_macroblock_ban_set(N-1) can trust it as anchor.
        let banned: Vec<String> = macroblock.consensus_data.banned_validators.as_deref()
            .and_then(|b| bincode::deserialize::<Vec<String>>(b).ok()).unwrap_or_default();
        if qnet_consensus::checkpoint_bft::epoch_commitment(elig, &cmt, &banned) != cp.epoch_commitment {
            return Err(format!("v2_epoch_uncertified mb={}", index));
        }
        // Observability backstop: independently re-derive the certified reward_root and ALARM on a
        // mismatch — but never reject. The committee already fail-stops on a divergent reward_root at
        // vote time (consensus_v2_node content_ok), so under the BFT bound (<1/3 Byzantine) the
        // 2f+1-certified root is honest by construction; a local disagreement therefore means OUR
        // tally is incomplete (fast-sync/snapshot), NOT that the root is forged. Rejecting a
        // QC-certified macroblock on a local recompute would stall exactly those catch-up nodes
        // (the recurring cold-start class) — so we trust the QC and let the adoption backstop
        // reconcile our local root. (Defending a >1/3-Byzantine committee is moot: that breaks
        // state_root too.) Only checked when the window is locally re-derivable (Some).
        if cp.reward_root != [0u8; 32] {
            let ci = qnet_consensus::checkpoint_bft::CHECKPOINT_INTERVAL;
            let start = cp.window_head_height.saturating_sub(ci).saturating_add(1);
            if let Some((root_hex, _, _, _)) = Self::compute_window_reward(storage, start, cp.window_head_height) {
                if root_hex != hex::encode(cp.reward_root) && is_warn() {
                    println!("[WARN][REWARDS] reward_root_local_mismatch mb={} (trusting 2f+1 QC; adoption reconciles)", index);
                }
            }
        }
        let verified = qc.verify(&committee, |voter, body, sig| match std::str::from_utf8(sig) {
            Ok(s) => p2p.verify_consensus_signature(voter, &format!("QNET_BFT2_VOTE:{}", hex::encode(body)), s),
            Err(_) => false,
        }).is_ok();
        if !verified {
            return Err(format!("v2_qc_invalid mb={} signers={} committee={}", index, qc.signers.len(), committee.len()));
        }
        Ok(())
    }

    async fn derive_v2_committee(&self, index: u64, head_height: u64) -> Vec<String> {
        let p2p = match self.unified_p2p.as_ref() { Some(p) => p, None => return Vec::new() };
        let qualified = Self::calculate_qualified_candidates(p2p, &self.node_id, self.node_type, head_height).await;
        let mut ids: Vec<String> = qualified.iter().map(|(id, _)| id.clone()).collect();
        ids.sort();
        Self::select_consensus_committee(&ids, index, &self.storage)
    }

    pub async fn process_received_macroblock(&self, received: crate::unified_p2p::ReceivedBlock) -> Result<(), QNetError> {
        let index = received.height;  // For macroblocks, height = index
        
        println!("[INFO][SYNC] macroblock_received index={} peer={}",
                 index, received.from_peer);
        
        // Decompress if needed
        let data = if received.data.len() >= 4 && received.data[0..4] == [0x28, 0xb5, 0x2f, 0xfd] {
            zstd::decode_all(&received.data[..])
                .map_err(|e| QNetError::StorageError(format!("Decompression failed: {}", e)))?
        } else {
            received.data.clone()
        };
        
        // Deserialize and validate macroblock
        let macroblock: qnet_state::MacroBlock = bincode::deserialize(&data)
            .map_err(|e| QNetError::ValidationError(format!("Invalid macroblock format: {}", e)))?;

        // Basic validation
        if macroblock.height != index {
            return Err(QNetError::ValidationError(format!(
                "Macroblock height mismatch: expected {}, got {}", index, macroblock.height
            )));
        }

        // Skip-marker macroblocks were legacy commit-reveal failover evidence — no longer
        // produced. Reject any (a forged is_skip_marker would otherwise bypass the
        // checkpoint-QC gate below). v2 finality is the 2f+1 checkpoint QC, nothing else.
        if macroblock.consensus_data.is_skip_marker {
            return Err(QNetError::ValidationError(format!("skip_marker_unsupported mb={}", index)));
        }

        // v2 (Checkpoint-BFT): finality is a 2f+1 QC over the checkpoint. checkpoint_qc
        // holds (Checkpoint, QC). Bind the block to the QC (hash + body match), derive the
        // committee deterministically (N-2 / genesis — NOT self-declared), and verify every
        // committee Dilithium signature. A forged committee or QC cannot pass. Bypass
        // commit/reveal (v2 has none).
        if let Some(cp_qc) = macroblock.consensus_data.checkpoint_qc.as_ref() {
            // FULL canonical verify (the SINGLE shared authority — same fn the block-pipeline accept
            // path uses, so neither can be bypassed). Binds every body field to the QC-certified
            // checkpoint, defers on a missing N-2 anchor, derives the committee deterministically,
            // and Dilithium-verifies every committee signature.
            let p2p = self.unified_p2p.as_ref()
                .ok_or_else(|| QNetError::ValidationError(format!("v2_no_p2p mb={}", index)))?;
            Self::verify_v2_macroblock(&macroblock, index, p2p, &self.node_id, self.node_type, &self.storage)
                .await
                .map_err(QNetError::ValidationError)?;
            if is_info() {
                println!("[INFO][MB] v2_qc_ok mb={}", index);
            }
            // C2: adopt the committee-certified reward root. If this node's locally-applied root for
            // an emission epoch differs (applied with incomplete data during catch-up), overwrite it
            // with the QC-certified Checkpoint.reward_root + re-derive the leaf set from the synced
            // window — never a single producer's TX root. Off state_root ⇒ cannot fork.
            if let Ok((cp, _qc)) = bincode::deserialize::<(qnet_consensus::checkpoint_bft::Checkpoint, qnet_consensus::checkpoint_bft::QuorumCertificate)>(cp_qc) {
                if cp.reward_root != [0u8; 32] {
                    let ci = qnet_consensus::checkpoint_bft::CHECKPOINT_INTERVAL;
                    let mbi = qnet_consensus::checkpoint_bft::MACROBLOCK_INTERVAL;
                    let start = cp.window_head_height.saturating_sub(ci).saturating_add(1);
                    let certified = hex::encode(cp.reward_root);
                    // The reward root is committee-verified (content_ok) + QC-signed ⇒ the 2f+1
                    // authority. Adopt it on EVERY finalizing node so claims verify everywhere. A
                    // local recompute that disagrees means OUR data is incomplete (catch-up), not
                    // that the root is wrong — never leave a node serving a divergent local root.
                    match Self::compute_window_reward(&self.storage, start, cp.window_head_height) {
                        // Re-derived root matches: store root + full leaf set (proofs available here).
                        Some((root_hex, wallets, _, epoch)) if root_hex == certified => {
                            let cur = self.storage.load_epoch_reward_root(epoch).ok().flatten().map(|(r, ..)| r);
                            if cur.as_deref() != Some(certified.as_str()) {
                                let rtotal: u64 = wallets.iter().map(|(_, a)| *a).sum();
                                let rcount = wallets.len() as u32;
                                let rper = if rcount > 0 { rtotal / rcount as u64 } else { 0 };
                                let _ = self.storage.save_epoch_reward_root(epoch, &certified, rper, rcount, rtotal);
                                let _ = self.storage.append_reward_epoch(epoch);
                                if is_info() { println!("[INFO][REWARDS] reward_root_adopted epoch={} root={}..", epoch, &certified[..16.min(certified.len())]); }
                            }
                            // Freeze the sharded leaf-set INDEPENDENTLY of the root-idempotency above: it
                            // re-derived to the 2f+1 CERTIFIED root (strongest authority). If an earlier
                            // finalization adopted the root ROOT-ONLY (incomplete data), the structure is
                            // still missing — write it now so claims load one shard, not a per-call recompute.
                            if self.storage.load_epoch_shard_meta(epoch).ok().flatten().is_none() {
                                Self::save_epoch_reward_sharded(&self.storage, epoch, &wallets);
                            }
                        }
                        // Leaf set not re-derivable here (incomplete/pruned/divergent): still adopt the
                        // certified ROOT under the canonical epoch so claims verify; wallets are served
                        // by synced peers. Epoch = boundary-height index − macroblocks/epoch (no scan).
                        other => {
                            // Keep the CONSERVED total (available when a set was re-derived, even if it
                            // mismatched the certified root) so a later recompute — once this node's data
                            // heals — can rebuild the leaf-set; None ⇒ no emission info ⇒ 0.
                            let (epoch, wtotal) = match other {
                                Some((_, _, t, e)) => (e, t),
                                None => ((cp.window_head_height / mbi).saturating_sub(14400 / mbi), 0),
                            };
                            let cur = self.storage.load_epoch_reward_root(epoch).ok().flatten().map(|(r, ..)| r);
                            if cur.as_deref() != Some(certified.as_str()) {
                                let _ = self.storage.save_epoch_reward_root(epoch, &certified, 0, 0, wtotal);
                                // A structure frozen earlier no longer recombines to the adopted certified root
                                // — drop it so the claim path rebuilds (verify-gated) instead of serving a stale
                                // set; a healed node then serves correctly, meanwhile wallets come via peers.
                                let _ = self.storage.delete_epoch_reward_shards(epoch);
                                let _ = self.storage.append_reward_epoch(epoch);
                                if is_warn() { println!("[WARN][REWARDS] reward_root_adopted_rootonly epoch={} (leaf set deferred; local recompute absent/divergent)", epoch); }
                            }
                        }
                    }
                }
            }
            // Catch-up safety-net (§4.5): hand the now-VERIFIED (checkpoint, QC) to the BFT2 driver so
            // a node whose consensus round fell behind the live quorum fast-forwards from committed
            // state. adopt_qc is monotonic ⇒ a no-op for a node already at/ahead of this checkpoint.
            crate::consensus_v2_node::signal_synced_checkpoint(cp_qc.clone());
        }

        // v2 finality is the 2f+1 checkpoint QC and nothing else. Skip-markers were rejected above, and
        // the honest network NEVER produces a None-QC macroblock (consensus always seals a checkpoint QC).
        // A None-QC macroblock reaching here is a forgery: the removed loose commit/reveal structural path
        // did NO signature verification yet the macroblock was still saved below, letting a byzantine
        // snapshot server inject a fabricated cold-join lineage (the N-2-derived committee would collapse
        // to the attacker's eligible_producers). Reject so "stored ⇒ QC-verified" holds for the cold-join
        // lineage walk — the same anchor_no_qc rule verify_snapshot_anchor_qc applies, now on every macroblock.
        if macroblock.consensus_data.checkpoint_qc.is_none() {
            return Err(QNetError::ValidationError(format!(
                "v2_qc_required mb={} reason=no_checkpoint_qc", index
            )));
        }

        // v3.00: Check if macroblock already saved (e.g., by BFT participant during consensus)
        // CRITICAL: Do NOT return early — emission rewards still need processing!
        // process_macroblock_heartbeats_deterministic has built-in dedup via processed_set
        let already_saved = self.storage.get_macroblock_by_height(index)
            .map(|mb| mb.is_some())
            .unwrap_or(false);
        
        if already_saved {
            // BFT participants save macroblock during consensus, broadcast arrives later
            // Skip save + validation, but continue to emission reward processing below
            if is_info() {
                println!("[INFO][MB-SYNC] already_saved mb={} skip_save process_rewards", index);
            }
            crate::unified_p2p::clear_macroblock_pending_sync(index);

            // v13.2: Update finality even for already-saved macroblocks. A macroblock can
            // be sealed/broadcast before its 90 microblocks land locally, so the earlier
            // try_advance_finality() call may have been a no-op; this second chance advances
            // finality once the body is complete.
            let round = index * 90;
            let prev_round = LAST_FINALIZED_CONSENSUS_ROUND.load(std::sync::atomic::Ordering::SeqCst);
            if round > prev_round {
                // v34: same ALL-microblocks-present guard as the save path below. Previously this
                // dedup branch advanced finality WITHOUT it, so a node that received the macroblock
                // (via BFT seal / broadcast) before its 90 microblocks could push LAST_FINALIZED
                // ahead of chain_height → stall-recovery rollback blocked by FINALITY_VIOLATION →
                // deadlock. Finality must never outrun the locally-applied microblock tip.
                let expected_start = if index == 1 { 1 } else { (index - 1) * 90 + 1 };
                let anchor_trusted = SNAPSHOT_ANCHOR_MB.load(std::sync::atomic::Ordering::SeqCst) >= index;
                let mut all_present = true;
                for h in expected_start..=index * 90 {
                    if self.storage.load_microblock(h)?.is_none() { all_present = false; break; }
                }
                if all_present || anchor_trusted {
                    if try_advance_finality(round, "MB-SYNC-DEDUP") {
                        println!("[INFO][MB-SYNC] finality_catchup mb={} round={} prev_round={}", index, round, prev_round);
                    }
                } else if is_debug() {
                    println!("[DBG][MB-SYNC] dedup_skip_finality mb={} round={} reason=missing_microblocks finality_at={}",
                             index, round, prev_round);
                }
            }
        } else {
            // New macroblock — validate, save, apply reputation
            
            // Validate microblock hashes exist (if we have the microblocks)
            let expected_start = if index == 1 { 1 } else { (index - 1) * 90 + 1 };
            let expected_end = index * 90;
            
            let mut missing_microblocks = Vec::new();
            for height in expected_start..=expected_end {
                if self.storage.load_microblock(height)?.is_none() {
                    missing_microblocks.push(height);
                }
            }
            
            if !missing_microblocks.is_empty() && is_debug() {
                // Expected during sync: macroblock headers arrive ahead of the microblocks the bulk
                // pipeline backfills bottom-up. A real stall surfaces via behind=/deadlock logs, not here.
                println!("[DBG][MB-SYNC] mb={} references {} missing microblocks (first {})",
                         index, missing_microblocks.len(), missing_microblocks[0]);
            }
            
            // Save macroblock to storage
            self.storage.save_macroblock(index, &macroblock).await?;

            // Advance the QC-verified frontier immediately on a QC-bearing commit (keeps the cached
            // gate fresh between probes; this is the sole commit-time writer the cache relies on).
            if macroblock.consensus_data.checkpoint_qc.is_some() {
                QC_VERIFIED_FRONTIER.fetch_max(index.saturating_mul(90), std::sync::atomic::Ordering::Relaxed);
            }

            // v3.1: Clear from pending sync tracker after successful save
            crate::unified_p2p::clear_macroblock_pending_sync(index);
            
            // v4.4: Only update finality if ALL microblocks are present.
            // Without this guard, a syncing node receives macroblocks via P2P before
            // the corresponding microblocks arrive. LAST_FINALIZED_HEIGHT jumps ahead
            // of chain_height → stall recovery rollback is blocked by FINALITY_VIOLATION
            // → permanent deadlock (node can't roll back OR advance).
            let round = index * 90;
            let prev_round = LAST_FINALIZED_CONSENSUS_ROUND.load(std::sync::atomic::Ordering::SeqCst);
            if round > prev_round {
                // mb <= snapshot anchor: trusted history — its 2f+1 QC already finalized it and the
                // snapshot carries the state, so finality advances without the sub-anchor microblocks
                // the snapshot legitimately omits. anchor==0 (warm node) ⇒ original present-guard.
                let anchor_trusted = SNAPSHOT_ANCHOR_MB.load(std::sync::atomic::Ordering::SeqCst) >= index;
                if missing_microblocks.is_empty() || anchor_trusted {
                    if try_advance_finality(round, "MB-SYNC") {
                        println!("[INFO][MB-SYNC] finalized_round_updated mb={} round={} finality_h={}", index, round, round);
                    }
                } else if is_debug() {
                    println!("[DBG][MB-SYNC] skip_finality_update mb={} round={} missing_microblocks={} finality_at={}",
                             index, round, missing_microblocks.len(), prev_round);
                }
            }
            
        }
        
        // ═══════════════════════════════════════════════════════════════════════════
        // v2.41.0: Apply heartbeat summaries from macroblock for deterministic rewards
        // CRITICAL: Only process at EMISSION MacroBlocks (every 160 macroblocks = 4 hours)
        // Heartbeats are recorded in each MacroBlock for sync, but rewards calculated only at emission
        // 
        // Math: 14400 microblocks / 90 blocks per macroblock = 160 macroblocks per 4h window
        // Emission MacroBlocks: 160, 320, 480, 640... (index % 160 == 0)
        // ═══════════════════════════════════════════════════════════════════════════
        const EMISSION_MACROBLOCK_INTERVAL: u64 = 160; // 14400 / 90 = 160 macroblocks per 4h
        let is_emission_macroblock = index > 0 && index % EMISSION_MACROBLOCK_INTERVAL == 0;
        
        if is_emission_macroblock {
            // Reward crediting is via the in-block emission TX (deterministic root + claims); this
            // sync-skippable handler only persists the periodic snapshot + dedup marker. Recipient
            // summaries are no longer sealed in the macroblock (O(1) at scale), so the reward_mgr
            // accounting below runs on an empty set (vestigial under the root model, harmless).
            {
                {
                    {
                        let heartbeat_summaries: Vec<qnet_state::HeartbeatSummary> = macroblock.consensus_data.reward_heartbeats.as_ref()
                            .and_then(|d| bincode::deserialize::<Vec<qnet_state::HeartbeatSummary>>(d).ok())
                            .unwrap_or_default();
                        // PRODUCTION v2.78: Merge Super nodes with Light nodes for unified processing
                        let mut all_summaries = heartbeat_summaries.clone();
                        
                        // Extract Light node rewards from MacroBlock
                        if let Some(ref light_data) = macroblock.consensus_data.reward_light_nodes {
                            if let Ok(light_node_rewards) = bincode::deserialize::<std::collections::HashMap<String, u32>>(light_data) {
                                // Convert Light nodes to HeartbeatSummary format
                                for (light_node_id, _ping_count) in &light_node_rewards {
                                    all_summaries.push(qnet_state::HeartbeatSummary {
                                        node_id: light_node_id.clone(),
                                        node_type: 0, // Light
                                        heartbeat_count: 1, // 1 ping per epoch
                                        first_heartbeat: 0,
                                        last_heartbeat: 0,
                                        is_eligible: true, // Already validated by PingCommitment
                                    });
                                }
                            }
                        }
                        
                        // Convert ALL nodes (Light + Super) to HeartbeatSummaryData
                        let summary_data: Vec<qnet_consensus::HeartbeatSummaryData> = all_summaries.iter()
                            .map(|s| qnet_consensus::HeartbeatSummaryData {
                                node_id: s.node_id.clone(),
                                node_type: s.node_type,
                                heartbeat_count: s.heartbeat_count,
                                first_heartbeat: s.first_heartbeat,
                                last_heartbeat: s.last_heartbeat,
                                is_eligible: s.is_eligible,
                            })
                            .collect();
                        
                        let reward_manager_arc = self.get_reward_manager();
                        let mut reward_mgr = reward_manager_arc.write().await;
                        let pool2_total = macroblock.consensus_data.pool2_total_fees;
                        let pool3_total = macroblock.consensus_data.pool3_total_activations;
                        
                        match reward_mgr.process_macroblock_heartbeats_deterministic(
                            index,
                            &summary_data,
                            pool2_total,
                            pool3_total,
                        ) {
                            Ok(was_processed) => {
                                if was_processed {
                                    let eligible = heartbeat_summaries.iter().filter(|s| s.is_eligible).count();
                                    if is_info() {
                                        println!("[INFO][REWARDS] SYNC rewards_calculated mb={} nodes={} eligible={}", 
                                                 index, heartbeat_summaries.len(), eligible);
                                    }
                                    
                                    // Update total_supply
                                    let total_emission = reward_mgr.get_last_epoch_emission();
                                    drop(reward_mgr);
                                    
                                    // Supply mint REMOVED here: total_supply is minted solely by the
                                    // in-block emission TX (state.emit_rewards, watermark-idempotent).
                                    // This macroblock handler is sync-skippable, so minting here was the
                                    // source of per-node total_supply divergence.
                                    let _ = total_emission;
                                    
                                    // v7.0: update_pending_rewards REMOVED — now applied via emission TX in block execution
                                    // Persist pending rewards to RocksDB (survive restarts)
                                    let reward_manager_arc = self.get_reward_manager();
                                    let mut updated_count = 0;
                                    {
                                        let reward_mgr_rd = reward_manager_arc.read().await;
                                        let accrual_node_ids: Vec<String> = reward_mgr_rd.get_last_epoch_accruals().keys().cloned().collect();
                                        for node_id in &accrual_node_ids {
                                            if let Some(reward) = reward_mgr_rd.get_pending_reward(node_id) {
                                                if let Err(e) = self.storage.save_pending_reward(node_id, reward) {
                                                    eprintln!("[WARN][REWARDS] pending_save_fail node={} err={}", node_id, e);
                                                } else {
                                                    updated_count += 1;
                                                }
                                            }
                                        }
                                    }
                                    
                                    if is_info() && updated_count > 0 {
                                        println!("[INFO][REWARDS] SYNC pending_persisted count={}", updated_count);
                                    }
                                    
                                    // state_snap_ RETIRED: local restart + reconcile now restore from the
                                    // apply-bound full_snap_ (created on the block_pipeline apply path at h=90 +
                                    // every SNAPSHOT_INCREMENTAL_INTERVAL) with total_supply from the QC-bound
                                    // checkpoint. This macroblock-handler capture read LIVE (drifting) state off
                                    // the apply path and was accounts+supply-only (incomplete) — one redundant,
                                    // drift-prone artifact removed; full_snap_ is the single snapshot.

                                    // Mark as processed
                                    let reward_manager_arc = self.get_reward_manager();
                                    let mut reward_mgr = reward_manager_arc.write().await;
                                    let mut processed_set = reward_mgr.get_processed_emission_macroblocks().clone();
                                    processed_set.insert(index);
                                    reward_mgr.set_processed_emission_macroblocks(processed_set.clone());
                                    drop(reward_mgr);
                                    
                                    if let Err(e) = self.storage.save_processed_emission_macroblocks(&processed_set) {
                                        eprintln!("[WARN][REWARDS] processed_save_fail mb={} err={}", index, e);
                                    }
                                } else {
                                    if is_warn() {
                                        println!("[WARN][REWARDS] SYNC already_processed mb={}", index);
                                    }
                                }
                            }
                            Err(e) => {
                                eprintln!("[ERR][REWARDS] SYNC process_fail mb={} err={}", index, e);
                            }
                        }
                    }
                }
            }
        }
        
        if is_info() && !already_saved { 
            println!("[INFO][MB-SYNC] saved mb={} microblocks={}", index, macroblock.micro_blocks.len()); 
        }
        
        Ok(())
    }
    
    /// Sync macroblocks from network
    /// PRODUCTION: Requests macroblocks from peers and waits for response
    pub async fn sync_macroblocks(&self, from_index: u64, to_index: u64) -> Result<(), QNetError> {
        // v13.0: Guard against inverted macroblock ranges
        if from_index > to_index {
            if is_warn() {
                println!("[WARN][SYNC] inverted_macroblock_range from={} to={} skipped", from_index, to_index);
            }
            return Ok(());
        }

        if let Some(ref p2p) = self.unified_p2p {
            if is_info() { println!("[INFO][SYNC] macroblock_sync from={} to={}", from_index, to_index); }
            // Single delegation to the P2P coordinator, which windows + overlap-dedups internally.
            // The old manual 10-wide re-batching here fought that window (overlapping chunks) — drop it.
            if let Err(e) = p2p.sync_macroblocks(from_index, to_index).await {
                if is_warn() { println!("[WARN][SYNC] macroblock_sync_failed from={} to={} err={}", from_index, to_index, e); }
            }
            Ok(())
        } else {
            Err(QNetError::NetworkError("P2P system not available".to_string()))
        }
    }
    
    /// Start the producer liveness watchdog: a 500 ms-tick tokio task that
    /// reads PRODUCER_HEARTBEAT_MS and warns on silence (3 s → producer_silent,
    /// 10 s → producer_dead), each escalation once per episode, re-armed on
    /// the next heartbeat. Log-only — never mutates producer state, emits BFT
    /// messages, or triggers view-change, so a false positive cannot fork the
    /// chain (failover stays driven solely by the 2f+1 timeout-vote path).
    fn start_producer_watchdog() {
        tokio::spawn(async move {
            use std::sync::atomic::Ordering;
            const TICK_MS: u64 = 500;
            const SILENT_THRESHOLD_MS: u64 = 3_000;
            const DEAD_THRESHOLD_MS: u64 = 10_000;

            let mut silent_warned = false;
            let mut dead_warned = false;
            let mut last_seen_heartbeat: u64 = 0;

            let mut interval = tokio::time::interval(std::time::Duration::from_millis(TICK_MS));
            interval.set_missed_tick_behavior(tokio::time::MissedTickBehavior::Delay);

            if is_info() {
                println!("[INFO][WATCHDOG] producer_watchdog_started tick_ms={} silent_ms={} dead_ms={}",
                         TICK_MS, SILENT_THRESHOLD_MS, DEAD_THRESHOLD_MS);
            }

            loop {
                interval.tick().await;

                let heartbeat = PRODUCER_HEARTBEAT_MS.load(Ordering::Relaxed);
                if heartbeat == 0 {
                    // Producer hasn't published its first heartbeat yet — still
                    // initialising. No silence to measure.
                    continue;
                }

                // Re-arm on heartbeat advance — recovered episode, allow fresh warnings.
                if heartbeat != last_seen_heartbeat {
                    if dead_warned {
                        if is_info() {
                            println!("[INFO][WATCHDOG] producer_recovered last_silence_at={}", last_seen_heartbeat);
                        }
                    }
                    last_seen_heartbeat = heartbeat;
                    silent_warned = false;
                    dead_warned = false;
                    continue;
                }

                let now_ms = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .map(|d| d.as_millis() as u64)
                    .unwrap_or(0);
                let silence_ms = now_ms.saturating_sub(heartbeat);

                if silence_ms >= DEAD_THRESHOLD_MS && !dead_warned {
                    println!(
                        "[WARN][WATCHDOG] producer_dead silence_ms={} last_heartbeat_ms={} action=observability_only",
                        silence_ms, heartbeat
                    );
                    dead_warned = true;
                } else if silence_ms >= SILENT_THRESHOLD_MS && !silent_warned {
                    println!(
                        "[WARN][WATCHDOG] producer_silent silence_ms={} last_heartbeat_ms={}",
                        silence_ms, heartbeat
                    );
                    silent_warned = true;
                }
            }
        });
    }

    /// Start health monitor for sync flags (prevents permanent deadlock)
    fn start_sync_health_monitor() {
        // PRODUCTION: Health check runs in background to detect and clear stuck sync flags
        tokio::spawn(async move {
            use std::sync::atomic::AtomicU64;
            
            // Track timestamps when flags were set
            #[allow(dead_code)]
            static FAST_SYNC_SET_AT: AtomicU64 = AtomicU64::new(0);
            #[allow(dead_code)]
            static NORMAL_SYNC_SET_AT: AtomicU64 = AtomicU64::new(0);
            
            loop {
                tokio::time::sleep(Duration::from_secs(30)).await;
                
                let _now = std::time::SystemTime::now()
                    .duration_since(std::time::UNIX_EPOCH)
                    .unwrap_or_default()
                    .as_secs();
                
                // Check FAST_SYNC_IN_PROGRESS health (defined in start_microblock_production)
                // Note: We cannot directly access the static from here, but we track timing
                
                // PRODUCTION: If a sync flag has been stuck for > 120 seconds, something is wrong
                // This is a safety net that should rarely trigger with Guard pattern in place
                
                println!("[INFO][SYNC] health_monitor_active interval=30s");
            }
        });
    }
    
    /// Query network height from connected peers
    pub async fn query_network_height(&self) -> Result<u64, QNetError> {
        if let Some(ref p2p) = self.unified_p2p {
            // Try to get cached network height first (fast path)
            if let Some(cached_height) = p2p.get_cached_network_height() {
                println!("[INFO][SYNC] cached_network_height h={}", cached_height);
                return Ok(cached_height);
            }
            
            // If no cache, query peers directly
            let peers = p2p.get_validated_active_peers();
            if peers.is_empty() {
                println!("[WARN][SYNC] No peers available, using local height");
                return Ok(self.get_height().await);
            }
            
            // v2.24.3: QUIC-ONLY SYNC - Use cached heights from PeerInfo
            // Heights are updated via heartbeats and block broadcasts (no HTTP queries needed)
            // SCALABILITY: O(n) where n = connected peers, zero network overhead
            let mut heights: Vec<u64> = peers.iter()
                .filter(|p| p.last_block_height > 0)  // Only peers with known height
                .map(|p| p.last_block_height)
                .collect();
            
            // Log peer heights for debugging
            for peer in peers.iter().filter(|p| p.last_block_height > 0).take(3) {
                println!("[DBG][SYNC] peer_height peer={} h={} source=cache", peer.id, peer.last_block_height);
            }
            
            // Take median height for Byzantine fault tolerance
            if !heights.is_empty() {
                heights.sort();
                let median = heights[heights.len() / 2];
                println!("[INFO][SYNC] network_consensus_height median={}", median);
                Ok(median)
            } else {
                println!("[WARN][SYNC] No cached peer heights - waiting for heartbeats, using local height");
                Ok(self.get_height().await)
            }
        } else {
            Err(QNetError::NetworkError("P2P network not initialized".to_string()))
        }
    }
    
    /// Recover consensus state after restart
    pub async fn recover_consensus_state(&self) -> Result<(), QNetError> {
        if let Some(ref p2p) = self.unified_p2p {
            // Get latest consensus round from storage
            let latest_round = self.storage.get_latest_consensus_round()?;
            
            if latest_round > 0 {
                println!("[INFO][CONS] request_state round={}", latest_round);
                
                // Request consensus state from peers
                if let Err(e) = p2p.sync_consensus_state(latest_round).await {
                    println!("[WARN][CONS] Failed to sync consensus state: {}", e);
                } else {
                    if is_info() { println!("[INFO][CONS] Consensus state sync initiated"); }
                }
            }
        }
        
        Ok(())
    }
    
    /// Auto-detect region from IP geolocation
    pub async fn auto_detect_region() -> Result<Region, String> {
        println!("[INFO][NODE] region_auto_detect method=geolocation");
        
        // Method 1: Check QNET_REGION environment variable
        if let Ok(region_hint) = std::env::var("QNET_REGION") {
            match region_hint.to_lowercase().as_str() {
                "na" | "northamerica" => return Ok(Region::NorthAmerica),
                "eu" | "europe" => return Ok(Region::Europe),
                "asia" => return Ok(Region::Asia),
                "sa" | "southamerica" => return Ok(Region::SouthAmerica),
                "africa" => return Ok(Region::Africa),
                "oceania" => return Ok(Region::Oceania),
                _ => {}
            }
        }
        
        // Method 2: Get external IP and use real geolocation services
        if let Ok(external_ip) = Self::get_physical_ip_without_external_services().await {
            println!("[DBG][NODE] geolocation_ip ip={}", external_ip);
            
            // Try multiple geolocation services for accuracy
            if let Ok(region) = Self::detect_region_via_geolocation_api(&external_ip).await {
                println!("[INFO][NODE] region_detected method=geolocation region={:?}", region);
                return Ok(region);
            }
        }
        
        // Method 3: Network latency testing (fallback)
        match Self::simple_latency_region_test().await {
            Ok(region) => {
                println!("[INFO][NODE] region_detected method=latency region={:?}", region);
                return Ok(region);
            }
            Err(e) => {
                println!("[WARN][NODE] latency_test_failed err={}", e);
            }
        }
        
        // Production: MUST detect region - no fallback defaults allowed
        Err("Production region detection failed - manual QNET_REGION environment variable required".to_string())
    }
    
    /// Detect region using real geolocation API services
    async fn detect_region_via_geolocation_api(ip: &str) -> Result<Region, String> {
        println!("[DBG][NODE] geolocation_query ip={}", ip);
        
        // Try multiple geolocation services for reliability
        let geolocation_services = vec![
            format!("https://ip-api.com/json/{}", ip),
            format!("https://ipapi.co/{}/json/", ip),
            format!("https://api.ipstack.com/{}?access_key=free", ip),
        ];
        
        for service_url in geolocation_services {
            match Self::query_geolocation_service(&service_url).await {
                Ok(region) => {
                    println!("[INFO][NODE] region_detected service={} region={:?}", service_url, region);
                    return Ok(region);
                }
                Err(e) => {
                    println!("[WARN][NODE] geolocation_failed service={} err={}", service_url, e);
                    continue;
                }
            }
        }
        
        Err("All geolocation services failed".to_string())
    }
    
    /// Query a specific geolocation service
    async fn query_geolocation_service(url: &str) -> Result<Region, String> {
        use std::time::Duration;
        
        let client = reqwest::Client::builder()
            .timeout(Duration::from_secs(15)) // PRODUCTION: Increased for Genesis node connectivity
            .build()
            .map_err(|e| format!("HTTP client error: {}", e))?;
        
        let response = client.get(url)
            .send()
            .await
            .map_err(|e| format!("Request failed: {}", e))?;
        
        if !response.status().is_success() {
            return Err(format!("HTTP error: {}", response.status()));
        }
        
        let json_text = response.text().await
            .map_err(|e| format!("Response read error: {}", e))?;
        
        println!("[DBG][NODE] geolocation_response body={}", json_text);
        
        // Parse JSON response
        let json_value: serde_json::Value = serde_json::from_str(&json_text)
            .map_err(|e| format!("JSON parse error: {}", e))?;
        
        // Extract continent/region information (try multiple fields)
        let region = if let Some(continent) = json_value.get("continent").and_then(|v| v.as_str()) {
            Self::map_continent_to_region(continent)
        } else if let Some(continent_code) = json_value.get("continent_code").and_then(|v| v.as_str()) {
            Self::map_continent_code_to_region(continent_code)
        } else if let Some(continent_code) = json_value.get("continentCode").and_then(|v| v.as_str()) {
            Self::map_continent_code_to_region(continent_code)
        } else if let Some(country_code) = json_value.get("country_code").and_then(|v| v.as_str()) {
            Self::map_country_code_to_region(country_code)
        } else if let Some(country_code) = json_value.get("countryCode").and_then(|v| v.as_str()) {
            Self::map_country_code_to_region(country_code)
        } else {
            return Err("No continent/country information in response".to_string());
        };
        
        region.ok_or_else(|| "Unknown region".to_string())
    }
    
    /// Map continent name to region
    fn map_continent_to_region(continent: &str) -> Option<Region> {
        match continent.to_lowercase().as_str() {
            "north america" | "northern america" => Some(Region::NorthAmerica),
            "europe" => Some(Region::Europe),
            "asia" => Some(Region::Asia),
            "south america" | "southern america" => Some(Region::SouthAmerica),
            "africa" => Some(Region::Africa),
            "oceania" | "australia" => Some(Region::Oceania),
            _ => None,
        }
    }
    
    /// Map continent code to region
    fn map_continent_code_to_region(code: &str) -> Option<Region> {
        match code.to_uppercase().as_str() {
            "NA" => Some(Region::NorthAmerica),
            "EU" => Some(Region::Europe),
            "AS" => Some(Region::Asia),
            "SA" => Some(Region::SouthAmerica),
            "AF" => Some(Region::Africa),
            "OC" => Some(Region::Oceania),
            _ => None,
        }
    }
    
    /// Map major country codes to regions (only essential ones)
    fn map_country_code_to_region(code: &str) -> Option<Region> {
        match code.to_uppercase().as_str() {
            // North America
            "US" | "CA" | "MX" => Some(Region::NorthAmerica),
            
            // Europe (major countries)
            "DE" | "FR" | "GB" | "ES" | "IT" | "NL" | "PL" | "RO" | "BE" | "CZ" |
            "PT" | "HU" | "SE" | "AT" | "CH" | "BG" | "DK" | "FI" | "NO" | "IE" => Some(Region::Europe),
            
            // Asia (major countries)  
            "CN" | "IN" | "JP" | "KR" | "TH" | "VN" | "SG" | "MY" | "PH" | "ID" |
            "TW" | "HK" | "BD" | "PK" => Some(Region::Asia),
            
            // South America
            "BR" | "AR" | "CL" | "CO" | "PE" | "VE" => Some(Region::SouthAmerica),
            
            // Africa (major countries)
            "ZA" | "NG" | "EG" | "KE" | "MA" => Some(Region::Africa),
            
            // Oceania
            "AU" | "NZ" => Some(Region::Oceania),
            
            _ => None,
        }
    }
    
    /// Save activation code to persistent storage with security validation
    pub async fn save_activation_code(&self, code: &str, node_type: NodeType) -> Result<(), QNetError> {
        // v3.18: Super node type removed - use 2 for Super (backward compatible)
        let node_type_id = match node_type {
            NodeType::Light => 0,
            NodeType::Super => 2,
        };
        
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();
        
        // Validate activation code format
        if code.is_empty() {
            return Err(QNetError::ValidationError("Empty activation code".to_string()));
        }
        
        // Check for genesis bootstrap codes first (different format)
        // IMPORT from shared constants to avoid duplication
        use crate::genesis_constants::GENESIS_BOOTSTRAP_CODES;
        let bootstrap_whitelist = GENESIS_BOOTSTRAP_CODES;
        
        let is_genesis_code = bootstrap_whitelist.contains(&code);
        
        // PRODUCTION: Initialize blockchain registry with real QNet nodes
        let qnet_rpc = std::env::var("QNET_RPC_URL")
            .or_else(|_| std::env::var("QNET_GENESIS_NODES")
                .map(|nodes| { let ip = nodes.split(',').next().unwrap_or("127.0.0.1").trim().to_string(); format!("http://{}:8001", ip) }))
            .unwrap_or_else(|_| "http://127.0.0.1:8001".to_string());
        
        if is_genesis_code {
            println!("[INFO][ACTIVATION] genesis_bootstrap_code code={}", code);
            // Skip format validation AND ownership check for genesis codes
            // Genesis codes are shared bootstrap codes with IP-based authentication
            println!("[INFO][ACTIVATION] genesis_code_skip_ownership auth=ip_based");
        } else {
            // Check basic format for regular codes (26-char format only)
            if !code.starts_with("QNET-") || code.len() != 25 {
                return Err(QNetError::ValidationError("Invalid activation code format. Expected: QNET-XXXXXX-XXXXXX-XXXXXX (25 chars)".to_string()));
            }
            
            let registry = crate::activation_validation::BlockchainActivationRegistry::new(
                Some(qnet_rpc.clone())
            );
            
            // v4.5: STATELESS verification — use env vars for burn_tx + burn_amount
            // Docker: -e QNET_BURN_TX_HASH=... -e QNET_BURN_AMOUNT=...
            // Code = XOR(wallet, SHA3(burn_tx:type:amount)) — self-contained, no node state needed
            let env_burn_tx = std::env::var("QNET_BURN_TX_HASH").unwrap_or_default();
            let env_burn_amount: u64 = std::env::var("QNET_BURN_AMOUNT")
                .unwrap_or_default()
                .parse()
                .unwrap_or(0);
            
            if !env_burn_tx.is_empty() && env_burn_amount > 0 {
                // v4.7: CRITICAL — derive Solana address from mnemonic and compare with XOR-decrypted wallet
                // This proves the mnemonic entered on the server belongs to the wallet that burned tokens.
                // Without this check, an attacker with stolen code+burn_tx could use ANY mnemonic.
                let wallet_seed = std::env::var("QNET_WALLET_SEED")
                    .or_else(|_| std::env::var("QNET_GENESIS_SEED"))
                    .unwrap_or_default();
                
                if wallet_seed.is_empty() {
                    return Err(QNetError::ValidationError(
                        "QNET_WALLET_SEED is required for super node activation".to_string()
                    ));
                }
                
                // Derive Solana address from mnemonic (same BIP44/SLIP-10 path as mobile app)
                let solana_from_mnemonic = crate::crypto::solana_derivation::derive_solana_address_from_mnemonic(&wallet_seed)
                    .map_err(|e| QNetError::ValidationError(
                        format!("Failed to derive Solana address from mnemonic: {}", e)
                    ))?;
                
                println!("[INFO][ACTIVATION] solana_from_mnemonic={}...", 
                    &solana_from_mnemonic[..16.min(solana_from_mnemonic.len())]);
                
                // STATELESS XOR verification — compare code's embedded wallet with mnemonic's Solana address
                // This is THE critical check: proves mnemonic owner == code owner
                match registry.verify_code_ownership_stateless(code, &solana_from_mnemonic, &env_burn_tx, env_burn_amount) {
                    Ok(true) => {
                        println!("[INFO][ACTIVATION] code_verified method=mnemonic_xor_match solana={}...",
                            &solana_from_mnemonic[..16.min(solana_from_mnemonic.len())]);
                        // G3-L1: admission-advisory — re-verify the 1DEV burn ACTUALLY happened on
                        // Solana. The XOR check above only proves code↔wallet↔CLAIMED-burn-params
                        // consistency (the params are operator-supplied), NOT that a real burn occurred;
                        // without this an operator self-derives a valid code with a fabricated burn_tx.
                        // Same live getTransaction the HTTP register paths enforce. Per-node (NOT
                        // consensus — a live RPC is non-deterministic and cannot be in apply), so it
                        // refuses to activate THIS node without a real burn yet can never fork. Genesis
                        // bootstrap codes don't set QNET_BURN_TX_HASH so this whole branch is skipped.
                        match crate::rpc::verify_burn_transaction_exists(
                            &env_burn_tx, &solana_from_mnemonic, env_burn_amount, 1,
                        ).await {
                            Ok((true, _)) => {
                                if is_info() {
                                    println!("[INFO][ACTIVATION] burn_verified_onchain tx={}...",
                                        &env_burn_tx[..16.min(env_burn_tx.len())]);
                                }
                            }
                            Ok((false, _)) => return Err(QNetError::ValidationError(format!(
                                "burn_not_found_on_solana tx={} amount={} — no real 1DEV burn backs this activation",
                                env_burn_tx, env_burn_amount,
                            ))),
                            Err(e) => return Err(QNetError::ValidationError(format!(
                                "burn_verify_error tx={} err={}", env_burn_tx, e,
                            ))),
                        }
                    }
                    Ok(false) => {
                        println!("[ERR][ACTIVATION] mnemonic_mismatch solana_from_seed={}... code_wallet=different",
                            &solana_from_mnemonic[..16.min(solana_from_mnemonic.len())]);
                        return Err(QNetError::ValidationError(
                            "Activation code does not belong to this mnemonic. \
                             The code was generated for a different wallet. \
                             Use the same seed phrase that was used in the mobile app when burning tokens.".to_string()
                        ));
                    }
                    Err(e) => {
                        return Err(QNetError::ValidationError(
                            format!("Activation code verification failed: {}. Check QNET_BURN_TX_HASH and QNET_BURN_AMOUNT.", e)
                        ));
                    }
                }
            } else {
                // No env burn data — REQUIRED for non-genesis nodes
                println!("[ERR][ACTIVATION] missing_burn_env_vars QNET_BURN_TX_HASH and QNET_BURN_AMOUNT required for super node activation");
                return Err(QNetError::ValidationError(
                    "QNET_BURN_TX_HASH and QNET_BURN_AMOUNT environment variables are required for super node activation. \
                     Get these from your mobile app: Settings > Export Activation Codes.".to_string()
                ));
            }
        }
        
        // v4.5: Get wallet and burn data — PREFER env vars (stateless), fallback to decrypt
        let (wallet_address, burn_tx_hash, phase, burn_amount) = {
            let env_burn_tx = std::env::var("QNET_BURN_TX_HASH").unwrap_or_default();
            let env_burn_amount: u64 = std::env::var("QNET_BURN_AMOUNT")
                .unwrap_or_default()
                .parse()
                .unwrap_or(0);
            
            if !env_burn_tx.is_empty() && env_burn_amount > 0 {
                // Stateless path: wallet derived from code via XOR decryption
                let wallet = self.get_wallet_address();
                // An env-provided burn_tx is always a 1DEV burn = activation Phase 1.
                let phase = 1;
                println!("[INFO][ACTIVATION] using_env_burn_data tx={}... amount={} phase={}",
                    &env_burn_tx[..16.min(env_burn_tx.len())], env_burn_amount, phase);
                (wallet, env_burn_tx, phase, env_burn_amount)
            } else {
                // Legacy path: decrypt code to get wallet + burn_tx
                let activation_payload = match self.decrypt_activation_code_full(code).await {
                    Ok(payload) => payload,
                    Err(e) => {
                        println!("[ERR][ACTIVATION] decrypt_failed={}", e);
                        println!("[ERR][ACTIVATION] Set QNET_BURN_TX_HASH and QNET_BURN_AMOUNT env vars for stateless activation");
                        return Err(QNetError::ValidationError(format!(
                            "Activation code decryption failed: {}. Set QNET_BURN_TX_HASH and QNET_BURN_AMOUNT.", e
                        )));
                    }
                };
                
                let wallet = activation_payload.wallet.clone();
                let btx = activation_payload.burn_tx.clone();
                
                let phase = if btx.starts_with("genesis_") || btx.starts_with("QNET-BOOT") {
                    1
                } else if btx.starts_with("pool3_transfer_") || btx.starts_with("qnet_") {
                    2
                } else if btx.len() == 88 || btx.len() == 87 {
                    1
                } else if btx.len() == 64 {
                    2
                } else {
                    1
                };
                
                // Get burn_amount from registry (stored when code was generated)
                let burn_amount = {
                    let registry_temp = crate::activation_validation::BlockchainActivationRegistry::new(
                        Some(qnet_rpc.clone())
                    );
                    let code_hash_temp = registry_temp.hash_activation_code_for_blockchain(code)
                        .unwrap_or_else(|_| {
                            format!("{:x}", Sha3_256::digest(code.as_bytes()))
                        });
                    
                    match registry_temp.get_activation_record_by_hash(&code_hash_temp).await {
                        Ok(Some(record)) => {
                            println!("   Burn Amount: {} (from registry)", record.activation_amount);
                            record.activation_amount
                        }
                        _ => {
                            let default_amount = if phase == 1 { 1500u64 } else { 5000u64 };
                            println!("   Burn Amount: {} (default for Phase {})", default_amount, phase);
                            default_amount
                        }
                    }
                };
                
                (wallet, btx, phase, burn_amount)
            }
        };
        
        println!("[INFO][ACTIVATION] payload_extracted wallet={}... burn_tx={}... phase={} burn_amount={}",
                 &wallet_address[..16.min(wallet_address.len())],
                 &burn_tx_hash[..16.min(burn_tx_hash.len())],
                 phase, burn_amount);
            
        // Create node info for blockchain registry with secure hash (SHA3-256 for NIST compliance)
        let registry = crate::activation_validation::BlockchainActivationRegistry::new(
            Some(qnet_rpc.clone())
        );
        let code_hash = registry.hash_activation_code_for_blockchain(code)
            .unwrap_or_else(|_| {
                format!("{:x}", Sha3_256::digest(code.as_bytes()))
            });
        
        let node_info = crate::activation_validation::NodeInfo {
            activation_code: code_hash, // Use hash for secure blockchain storage
            wallet_address: wallet_address.clone(),
            device_signature: self.get_device_signature(),
            node_type: format!("{:?}", node_type),
            activated_at: timestamp,
            last_seen: timestamp,
            migration_count: 0,
            node_id: self.node_id.clone(), // CRITICAL: Link activation_code to network node_id
            burn_tx_hash: burn_tx_hash.clone(), // CRITICAL: Store burn_tx for XOR decryption
            phase, // Determined from burn_tx format
            burn_amount, // CRITICAL: Store exact amount for XOR key derivation
        };
        
        // FIXED: Register activation with device migration support
        // This updates the device_signature in global registry, causing old devices to deactivate
        if let Err(e) = registry.register_or_migrate_device(code, node_info, &self.get_device_signature()).await {
            println!("[WARN][ACTIVATION] device_register_failed err={}", e);
            // Continue with local storage only
        } else {
            println!("[INFO][ACTIVATION] device_registered migration=auto_deactivate_old");
        }
        
        // Save to local storage
        self.storage.save_activation_code(code, node_type_id, timestamp)
            .map_err(|e| QNetError::StorageError(e.to_string()))?;
        
        // CRITICAL: Save burn_tx_hash for future XOR decryption (e.g., after node restart)
        // This allows the node to re-derive the encryption key without re-querying blockchain
        if let Err(e) = self.storage.save_activation_burn_tx(&burn_tx_hash) {
            println!("[WARN][ACTIVATION] burn_tx_save_failed err={}", e);
            // Non-fatal - burn_tx can be retrieved from registry if needed
        } else {
            println!("[INFO][ACTIVATION] burn_tx_saved");
        }
        
        // Register Super nodes in reward system (not Genesis or Light nodes)
        // Light nodes register through mobile app via RPC
        // Genesis nodes register separately
        if !bootstrap_whitelist.contains(&code) && node_type != NodeType::Light {
            // v3.18: Super node type removed
            let mut reward_manager = self.reward_manager.write().await;
            let reward_node_type = match node_type {
                NodeType::Super => RewardNodeType::Super,
                NodeType::Light => RewardNodeType::Light,
            };
            
            if let Err(e) = reward_manager.register_node(
                self.node_id.clone(),
                reward_node_type,
                wallet_address.clone()
            ) {
                eprintln!("[WARN][REWARDS] Failed to register node in reward system: {}", e);
            } else {
                if is_info() { println!("[INFO][REWARDS] node_registered id={} type={:?}", 
                         self.node_id, node_type); }
                if is_debug() { println!("[DBG][REWARDS] wallet={}...", &wallet_address[..20.min(wallet_address.len())]); }
            }
            
            // v2.71: Create ON-CHAIN NodeRegistration TX for Super nodes
            // This ensures wallet→node binding is immutable and verifiable by all nodes
            // v3.18: Super node type removed
            let qnet_node_type = match node_type {
                NodeType::Super => qnet_state::NodeType::Super,
                NodeType::Light => qnet_state::NodeType::Light,
            };
            
            // Use activation code hash as registration proof
            let registration_proof = registry.hash_activation_code_for_blockchain(code)
                .unwrap_or_else(|_| blake3::hash(code.as_bytes()).to_hex().to_string());
            
            // v3.35: Auto-detect public API endpoint for Super nodes
            // By default = PUBLIC (auto-detect IP)
            // Set QNET_HIDE_IP=1 to hide your IP (empty endpoint)
            let api_endpoint = if qnet_node_type == qnet_state::NodeType::Super {
                if std::env::var("QNET_HIDE_IP").is_ok() {
                    // Operator explicitly chose to hide IP
                    String::new()
                } else {
                    // Auto-detect public IP and create endpoint
                    let public_ip = std::env::var("QNET_PUBLIC_IP")
                        .or_else(|_| std::env::var("EXTERNAL_IP"))
                        .or_else(|_| std::env::var("HOST_IP"))
                        .unwrap_or_default();
                    
                    if !public_ip.is_empty() {
                        format!("http://{}:8001", public_ip)
                    } else {
                        // No IP detected - node won't serve mobile apps
                        String::new()
                    }
                }
            } else {
                // Light nodes: NEVER have api_endpoint (privacy)
                String::new()
            };
            
            let mut registration_tx = Self::create_node_registration_tx_with_endpoint(
                &self.node_id,
                qnet_node_type,
                &wallet_address,
                &registration_proof,
                &api_endpoint,
            );

            // Phase-1 burn-attestation (PRODUCTION half): when the gate is active, collect the genesis
            // quorum that proves the Solana 1DEV burn on-chain and embed it so block validation accepts
            // the registration. Inert below the gate height ⇒ current onboarding is byte-for-byte
            // unchanged (this whole block is skipped). Set before the final hash below.
            {
                let cur_h = self.storage.get_chain_height().unwrap_or(0);
                if qnet_state::feature_gates::is_active("burn_attestation_required", cur_h) {
                    let b_tx = std::env::var("QNET_BURN_TX_HASH").unwrap_or_default();
                    let b_amt: u64 = std::env::var("QNET_BURN_AMOUNT").ok().and_then(|s| s.parse().ok()).unwrap_or(0);
                    let mnemonic = std::env::var("QNET_WALLET_SEED").unwrap_or_default();
                    let solana_wallet = crate::crypto::solana_derivation::derive_solana_address_from_mnemonic(&mnemonic)
                        .unwrap_or_default();
                    if !b_tx.is_empty() && !solana_wallet.is_empty() {
                        // Re-derive (qnet_node_type was moved into the registration builder above).
                        let qnt = match node_type {
                            NodeType::Super => qnet_state::NodeType::Super,
                            NodeType::Light => qnet_state::NodeType::Light,
                        };
                        // Local Phase-1 cost (advisory hint only); each attestor recomputes + signs its own.
                        let cost_hint = match crate::rpc::fetch_solana_1dev_supply().await {
                            Ok((tb, cs)) => qnet_state::Transaction::phase1_activation_cost(tb, cs),
                            Err(_) => 0,
                        };
                        // QNET_BURN_AMOUNT (b_amt) is now only an operator hint; the embedded burn_amount
                        // is the committee-certified agreed_amount (== what the counted 2f+1 signed), so an
                        // honest over-burn (declared < actual) still verifies. For the exact-burn case
                        // (declared == actual) agreed_amount == b_amt ⇒ identical registration as before.
                        let (attestors, agreed_cost, agreed_amount) = Self::collect_burn_attestations(
                            &b_tx, &solana_wallet, &wallet_address, b_amt, qnt, cost_hint, &self.storage).await;
                        let need = qnet_consensus::checkpoint_bft::quorum_size(
                            crate::genesis_constants::genesis_node_count());
                        if attestors.len() < need {
                            // Sub-quorum ⇒ ABORT the arm (return Err) so the single-owner onboarding driver
                            // re-collects fresh attestations against the current committee next tick. Arming a
                            // sub-quorum TX would rebroadcast fixed bytes every validator rejects forever (the
                            // permanent-wedge anti-pattern). Likely transient cause surfaced for the operator.
                            eprintln!("[WARN][REG] burn_attest_sub_quorum got={}/{} declared={} — retrying arm (check committee :8001 + Solana burn-RPC reachability)",
                                      attestors.len(), need, b_amt);
                            return Err(QNetError::NetworkError(format!(
                                "burn_attest_sub_quorum got={} need={}", attestors.len(), need)));
                        }
                        if let qnet_state::TransactionType::NodeRegistration {
                            burn_tx: bt, burn_amount: ba, burn_cost: bc, burn_attestors: at, ..
                        } = &mut registration_tx.tx_type {
                            *bt = b_tx; *ba = agreed_amount; *bc = agreed_cost; *at = attestors;
                        }
                    }
                }
            }

            // Pure ML-DSA-65 signing for User Super Nodes. Keys are created ON THIS NODE — sign
            // locally before submitting to mempool. This prevents any block producer from forging
            // a NodeRegistration for a foreign wallet: the wallet MUST be the EON derived from this
            // Dilithium key (native_bound, verified at block validation). Ed25519 was an illusory
            // leg — quantum-breakable, no identity binding — removed.
            {
                let canonical_msg = format!("client_node_reg:{}:{}:{}:{}",
                    self.node_id, wallet_address, registration_proof, registration_tx.timestamp);

                // Dilithium3 from WalletIdentity (post-quantum)
                // Uses consensus-compatible format: "dilithium_sig_{node_id}_{base64(...)}"
                // PK is embedded inside the base64 payload — TX is self-contained.
                if let Some(ref identity) = self.wallet_identity {
                    match identity.sign_consensus(&self.node_id, canonical_msg.as_bytes()) {
                        Ok(consensus_sig) => {
                            registration_tx.dilithium_signature = Some(consensus_sig);
                            registration_tx.dilithium_public_key = Some(hex::encode(&identity.dilithium_pk));
                        }
                        Err(e) => {
                            eprintln!("[WARN][REG] dilithium3_sign_failed: {}", e);
                        }
                    }
                }

                // Mark as client-signed → other nodes MUST verify both signatures
                registration_tx.data = Some(format!("client_node_reg:{}:{}:{}:",
                    self.node_id, wallet_address, registration_proof));
                registration_tx.hash = registration_tx.calculate_hash();

                println!("[INFO][REG] signed dilithium3={} node={}",
                    registration_tx.dilithium_signature.is_some(),
                    self.node_id);
            }
            
            // Add to mempool for inclusion in next block
            let tx_bytes = bincode::serialize(&registration_tx).unwrap_or_default();
            let tx_hash = registration_tx.hash.clone();
            if self.mempool.add_binary_transaction(tx_bytes.clone(), tx_hash.clone(), 0) {
                if is_info() {
                    println!("[INFO][REG] onchain_tx_submitted node={} wallet={}... hash={}...",
                             self.node_id,
                             &wallet_address[..16.min(wallet_address.len())],
                             &tx_hash[..16.min(tx_hash.len())]);
                }
                // Arm the backoff rebroadcast: the periodic loop re-sends this until it lands on-chain
                // (burst then trickle). The third field is the backoff tick counter — start at 0.
                if let Ok(mut pend) = PENDING_NODE_REGISTRATION.lock() {
                    *pend = Some((self.node_id.clone(), tx_bytes.clone(), 0));
                }
                // Deliver with the same guarantee as NodeActivation: producer-direct gossip + direct
                // fan-out to every genesis node. A fresh joiner usually has no producer info yet, so a
                // single gossip is fragile; the genesis fan-out ensures the binding TX reaches the
                // network even before sync completes.
                if let Some(ref p2p) = self.unified_p2p {
                    let _ = p2p.broadcast_transaction(tx_bytes.clone());
                    let tx_msg = crate::unified_p2p::NetworkMessage::Transaction { data: tx_bytes };
                    let genesis_ips = crate::unified_p2p::get_genesis_bootstrap_ips();
                    for ip in &genesis_ips {
                        p2p.send_network_message(&format!("{}:8001", ip), tx_msg.clone());
                    }
                    if is_info() { println!("[INFO][REG] registration_tx_broadcast hash={} genesis={}", &tx_hash[..16.min(tx_hash.len())], genesis_ips.len()); }
                }
            } else {
                // TX did not enter the local mempool (pool full / already-present race) ⇒ PENDING is NOT
                // armed and the rebroadcast has nothing to send. Return Err so the onboarding driver retries
                // the arm instead of breaking into production unregistered (the M-1 validator-only failure).
                eprintln!("[WARN][REG] onchain_tx_failed node={} — will retry", self.node_id);
                return Err(QNetError::NetworkError(format!("registration_tx_not_submitted node={}", self.node_id)));
            }
        }

        // v4.9: USER SUPER NODE MIGRATION TRACKING
        // Register device_id on a genesis node's RocksDB via lightweight REST API.
        // Flow: Super node starts → POST /api/v1/register-device → genesis stores device_id.
        // If the same activation code is used on a NEW server, genesis updates device_id.
        // Old server polls GET /api/v1/node-device every 30s → sees different device_id → graceful shutdown.
        // NOTE: Genesis nodes are EXCLUDED (they use IP-based auth, not activation codes).
        if !is_genesis_code {
            let device_sig = self.get_device_signature();
            let genesis_url = std::env::var("QNET_RPC_URL")
                .or_else(|_| std::env::var("QNET_GENESIS_NODES")
                    .map(|nodes| { let ip = nodes.split(',').next().unwrap_or("127.0.0.1").trim().to_string(); format!("http://{}:8001", ip) }))
                .unwrap_or_else(|_| "http://127.0.0.1:8001".to_string());
            
            let node_id_for_log = self.node_id.clone();
            let node_id_for_body = self.node_id.clone();
            let device_sig_clone = device_sig.clone();
            
            // Non-blocking: POST device_id to genesis node's RocksDB storage
            tokio::spawn(async move {
                let client = match reqwest::Client::builder()
                    .timeout(std::time::Duration::from_secs(10))
                    .build() {
                    Ok(c) => c,
                    Err(_) => return,
                };
                let url = format!("{}/api/v1/register-device", genesis_url);
                let body = serde_json::json!({
                    "node_id": node_id_for_body,
                    "device_id": device_sig_clone,
                });
                match client.post(&url).json(&body).send().await {
                    Ok(resp) => {
                        if let Ok(json) = resp.json::<serde_json::Value>().await {
                            if json["success"].as_bool() == Some(true) {
                                println!("[INFO][ACTIVATION] device_registered_on_genesis node={}", node_id_for_log);
                            } else if is_debug() {
                                // Transient until the joiner's registration finalizes network-side; auto-retried.
                                println!("[DBG][ACTIVATION] device_register_rejected node={} err={}",
                                    node_id_for_log, json["error"].as_str().unwrap_or("unknown"));
                            }
                        }
                    }
                    Err(e) => {
                        println!("[WARN][ACTIVATION] device_register_failed node={} err={}", node_id_for_log, e);
                    }
                }
            });
        }
        
        println!("[INFO][ACTIVATION] code_saved binding=blockchain_registry");
        Ok(())
    }
    
    /// Load activation code from persistent storage
    pub async fn load_activation_code(&self) -> Result<Option<(String, NodeType)>, QNetError> {
        match self.storage.load_activation_code()
            .map_err(|e| QNetError::StorageError(e.to_string()))? {
            Some((code, node_type_id, _timestamp)) => {
                // v3.18: Super node type removed - map old Full (1) to Super
                let node_type = match node_type_id {
                    0 => NodeType::Light,
                    2 => NodeType::Super,
                    1 => {
                        // v3.18: Old Super node type - upgrade to Super for backward compatibility
                        println!("[INFO][NODE] full_to_super_migration node_type_id=1");
                        NodeType::Super
                    },
                    _ => {
                        println!("[WARN][NODE] unknown_node_type id={} defaulting=Light", node_type_id);
                        NodeType::Light // Default to Light for unknown types
                    },
                };
                
                // Check if activation is still valid (codes never expire - tied to blockchain burns)
                println!("[INFO][ACTIVATION] valid_code_loaded binding=crypto");
                Ok(Some((code, node_type)))
            }
            None => Ok(None),
        }
    }
    
    /// Clear activation code from storage
    pub async fn clear_activation_code(&self) -> Result<(), QNetError> {
        self.storage.clear_activation_code()
            .map_err(|e| QNetError::StorageError(e.to_string()))?;
        Ok(())
    }
    
    /// Migrate device (same wallet, different device)
    pub async fn migrate_device(&self, code: &str, node_type: NodeType, new_device_signature: &str) -> Result<(), QNetError> {
        // v3.18: Super node type removed - use 2 for Super (backward compatible)
        let node_type_id = match node_type {
            NodeType::Light => 0,
            NodeType::Super => 2,
        };
        
        let timestamp = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs();
        
        // Update activation record for device migration
        self.storage.update_activation_for_migration(code, node_type_id, timestamp, new_device_signature)
            .map_err(|e| QNetError::StorageError(e.to_string()))?;
        
        println!("[INFO][ACTIVATION] device_migrated sig={}", new_device_signature);
        Ok(())
    }
    
